WITH scored AS (SELECT *, SUM(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, SUM(duration_sec) OVER (PARTITION BY page ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec_2, NTILE(5) OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id ASC) AS duration_sec_bucket, AVG(duration_sec) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_avg_7d FROM web_events) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, COUNT(*) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_rows, SUM(CASE WHEN page = '/checkout' THEN duration_sec ELSE 0 END) AS checkout_duration_sec, PERCENTILE_APPROX(cumulative_duration_sec_2, ARRAY(0.25, 0.5, 0.75)) AS cumulative_duration_sec_2_quartiles FROM scored GROUP BY DATE_TRUNC('WEEK', event_time) ORDER BY checkout_duration_sec DESC NULLS LAST;
